// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(address baseToken, address nft, uint16 feeRate) public {
        // admissible domain: nonzero base token, valid fee rate
        vm.assume(baseToken != address(0));
        vm.assume(feeRate <= 5_000);

        // fresh pool so initialize has not run yet for this fuzz iteration
        c = new PrivatePool(address(this), address(this), address(this));

        bool ok;
        try c.initialize(
            baseToken,
            nft,
            1e18,
            1e18,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        ) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: whenever initialize succeeds with a nonzero base token,
        // the pool's public surface must report that base token back.
        assertTrue(ok && c.flashFeeToken() == baseToken);
    }
}
